// Pre for both functions: fichas is between 0 and 12.
int parejas_recursivas(int fichas) {
    if (fichas < 2) {
        return 0;
    }
    return 1 + parejas_recursivas(fichas - 2);
}

int parejas_iterativas(int fichas) {
    int pendientes = fichas;
    int parejas = 0;
    while (pendientes >= 2) {
        pendientes -= 2;
        ++parejas;
    }
    return parejas;
}

int main() {
    const int fichas = 8;
    if (fichas < 0 || fichas > 12) {
        std::cout << "Outside the domain";
        return 0;
    }
    const int recursivas = parejas_recursivas(fichas);
    const int iterativas = parejas_iterativas(fichas);
    std::cout << recursivas << ":" << iterativas << ":" << fichas;
    return 0;
}

